<?php
/** Offline dispatch tests: synthetic WordPress requests/responses, SQLite accounts and a non-expiring rate counter. Not HTTP/MySQL proof. */
define('ARRAY_A','ARRAY_A');
foreach(array('schema','database','vault','compat','config','auth','auth-routes','plugin') as $n){require __DIR__.'/../sender-suite/includes/class-'.$n.'.php';}
require __DIR__.'/sqlite-auth-db.php';
function home_url($path){return 'https://synthetic.example.test/';}
function wp_parse_url($url){return parse_url($url);}
function wp_unslash($value){return stripslashes($value);}
class WP_REST_Response {public $data;public $status;public $headers=array();public function __construct($data,$status){$this->data=$data;$this->status=$status;}public function header($name,$value){$this->headers[$name]=$value;}}
final class SyntheticRequest {private $path;private $body;public $headers;public $query=array();public function __construct($path,$body='',$headers=array()){$this->path='/sender-suite/v1/'.$path;$this->body=$body;$this->headers=$headers;}public function get_route(){return $this->path;}public function get_body(){return $this->body;}public function get_header($name){return $this->headers[$name]??'';}public function get_query_params(){return $this->query;}public function set_query_params($q){$this->query=$q;}}
$count=0;$diff=array();
function route_check($name,$actual,$expected){global $count,$diff;if($actual===$expected){$count++;}elseif(count($diff)<10){$diff[]=array('name'=>$name,'actual'=>$actual,'expected'=>$expected);}}
function route_context($ready=true,$limit='100/minute'){$w=new SQLiteAuthDB();$db=new \SenderSuite\Database($w,new \SenderSuite\Schema('test_'));$store=array();$cfg=new \SenderSuite\Config(new \SenderSuite\Vault(str_repeat('synthetic-vault-',4)),function()use(&$store){return $store;},function($v)use(&$store){$store=$v;});if($ready){$cfg->setup('operator','synthetic-secret');}$cfg->save(array('RATE_LIMIT_LOGIN'=>$limit));$codec=new class{public function hash($value){return 'synthetic:'.$value;}public function verify($value,$hash){return $hash==='synthetic:'.$value;}};$context=array('db'=>$db,'config'=>$cfg,'auth'=>new \SenderSuite\AppAuth($db,$cfg,$codec),'prefix'=>'test_');$p=new ReflectionProperty(\SenderSuite\AuthRoutes::class,'context');$p->setAccessible(true);$p->setValue(null,$context);return array($context,$w);}
function dispatch_test($path,$body='',$headers=array()){return \SenderSuite\AuthRoutes::dispatch(new SyntheticRequest($path,$body,$headers));}
$_COOKIE=array();$_SERVER['REMOTE_ADDR']='192.0.2.1';
list($c,$w)=route_context(false);$r=dispatch_test('auth/access');route_check('unconfigured API fails closed',$r->status,503);route_check('no cookie before setup',isset($r->headers['Set-Cookie']),false);
list($c,$w)=route_context();
foreach(array('https://evil.example','http://synthetic.example.test','https://synthetic.example.test:444','null','https://user@synthetic.example.test','https://synthetic.example.test/?x=1','https://synthetic.example.test/#x') as $origin){$r=dispatch_test('auth/access','',array('origin'=>$origin));route_check('reject origin '.$origin,$r->status,403);}
$r=dispatch_test('auth/access','',array('sec-fetch-site'=>'cross-site'));route_check('reject cross-site without Origin',$r->status,403);
foreach(array('https://synthetic.example.test','https://synthetic.example.test:443','https://synthetic.example.test/') as $origin){$r=dispatch_test('auth/access','',array('origin'=>$origin));route_check('accept same origin '.$origin,$r->status,200);}
$r=dispatch_test('auth/access');route_check('access no-store',$r->headers['Cache-Control'],'no-store');route_check('request ID length',strlen($r->headers['X-Request-ID']),32);route_check('access has source flags',isset($r->data['password_required']),true);
$r=dispatch_test('auth/login','{"username":"operator","password":"wrong"}');route_check('wrong password',$r->status,401);route_check('failed login rolls back administrator seed',$c['db']->select('users',array(),100),array());route_check('failed login has no cookie',isset($r->headers['Set-Cookie']),false);route_check('error request ID matches header',$r->data['request_id'],$r->headers['X-Request-ID']);
foreach(array('','{','[]','{"password":4}') as $raw){$r=dispatch_test('auth/login',$raw);route_check('invalid input '.$raw,$r->status,422);route_check('validation error code '.$raw,$r->data['code'],'VALIDATION_ERROR');}
$r=dispatch_test('auth/admin');route_check('missing optional admin body is wrong password',$r->status,401);route_check('admin failure rollback',$c['db']->select('users',array(),100),array());
$r=dispatch_test('auth/login','{"username":"operator","password":"synthetic-secret"}');route_check('valid login',$r->status,200);$cookie=$r->headers['Set-Cookie']??'';foreach(array('sendsms_session=','Path=/','HttpOnly','SameSite=lax','Secure','Max-Age=86400') as $part){route_check('cookie attribute '.$part,strpos($cookie,$part)!==false,true);}preg_match('/^sendsms_session=([^;]+)/',$cookie,$m);$_COOKIE['sendsms_session']=$m[1]??'';route_check('login committed one account',count($c['db']->select('users',array(),100)),1);route_check('no token JSON leak',isset($r->data['token']),false);
$r=dispatch_test('auth/me');route_check('own account session',$r->status,200);route_check('own username',$r->data['username']??null,'operator');route_check('no password hash in response',isset($r->data['password_hash']),false);$id=$r->data['id'];$c['db']->update('users',array('role'=>'staff'),array('id'=>$id));$r=dispatch_test('auth/me');route_check('role comes from current database',$r->data['role']??null,'staff');
$r=dispatch_test('auth/logout');route_check('logout',$r->status,200);route_check('logout expires cookie',strpos($r->headers['Set-Cookie'],'Max-Age=0')!==false,true);$_COOKIE=array();$r=dispatch_test('auth/me');route_check('missing session',$r->status,401);$_COOKIE['sendsms_session']='tampered.token.value';route_check('invalid session',dispatch_test('auth/me')->status,401);$_COOKIE['sendsms_session']=$m[1];$c['db']->update('users',array('is_active'=>false),array('id'=>$id));route_check('inactive user rejected',dispatch_test('auth/me')->status,401);$_COOKIE=array();
list($c,$w)=route_context(true,'2/minute');for($i=1;$i<=3;$i++){$r=dispatch_test('auth/login','{"password":"wrong"}',array('x-forwarded-for'=>'198.51.100.'.$i));route_check('rate attempt '.$i,$r->status,$i<3?401:429);}route_check('rate Retry-After',$r->headers['Retry-After'],'60');route_check('forwarded header cannot evade counter',count($w->rates),1);route_check('admin has independent route bucket',dispatch_test('auth/admin','{"password":"wrong"}')->status,401);$_SERVER['REMOTE_ADDR']='192.0.2.2';route_check('separate peer bucket',dispatch_test('auth/login','{"password":"wrong"}')->status,401);
$q=new SyntheticRequest('auth/me');$q->query=array('_jsonp'=>'callback','_envelope'=>'1','_fields'=>'username','_embed'=>'1','_method'=>'POST','safe'=>'preserved');$marker=(object)array('preserved'=>true);route_check('pre-dispatch preserves prior result',\SenderSuite\Plugin::sourceRequest($marker,null,$q)===$marker,true);route_check('query hardening',$q->query,array('safe'=>'preserved'));
